<template><div class="auth-page"><div class="auth-card"><div class="brand"><span class="brand-mark">M</span><div><strong>MianMian</strong><small>面面俱道 · AI 面试训练场</small></div></div><h2>学生登录</h2><p class="muted">用户名、密码和班级由教师统一分配</p><p v-if="error" class="error">{{ error }}</p><input v-model="username" placeholder="用户名" autocomplete="username"><input v-model="password" type="password" placeholder="密码" autocomplete="current-password"><button class="primary" :disabled="busy" @click="login">{{ busy?'登录中…':'进入训练场' }}</button><button class="link-btn" @click="showPassword=!showPassword">修改密码</button><div v-if="showPassword" class="password-box"><input v-model="oldPassword" type="password" placeholder="原密码"><input v-model="newPassword" type="password" placeholder="新密码（至少6位）"><button class="secondary" @click="changePassword">保存新密码</button></div></div></div></template>
<script setup>
import { ref } from 'vue'; import { useRouter } from 'vue-router'; import { request } from '../api'
const router=useRouter(),username=ref(''),password=ref(''),oldPassword=ref(''),newPassword=ref(''),error=ref(''),busy=ref(false),showPassword=ref(false)
async function login(){busy.value=true;error.value='';try{const u=await request('/api/v1/auth/login',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({username:username.value,password:password.value})});localStorage.setItem('mianmian-token',u.access_token);localStorage.setItem('mianmian-user',JSON.stringify(u));router.push(u.role==='TEACHER'?'/teacher':'/')}catch(e){error.value=e.message}finally{busy.value=false}}
async function changePassword(){try{await request('/api/v1/auth/password',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({username:username.value,old_password:oldPassword.value,new_password:newPassword.value})});error.value='密码已更新'}catch(e){error.value=e.message}}
</script>
